# aplica los textos de la v185 a CHANGELOG.md y CLAUDE.md (archivo de entrada -> salida); uso: docs185.py changelog|claude ENT SAL
import sys, json
modo, ent, sal = sys.argv[1:4]
V = json.load(open(sys.argv[4])) if len(sys.argv) > 4 else {}
t = open(ent, encoding='utf-8').read()
def ins_antes(t, ancla, txt):
    i = t.find(ancla); assert i >= 0, ancla[:60]; return t[:i] + txt + t[i:]
SELLO, SHA_O, SHA_I, PRU, BASE = V.get('sello', 'SELLO185'), V.get('o', ''), V.get('i', ''), V.get('pruebas', 'PRUEBAS185'), V.get('base', 'el ORIGINAL 183 (`0650f1a4…`)')
if modo == 'changelog':
    if '## v185 ' in t: print('ya'); sys.exit(0)
    txt = f'''## v185 — 19/11/2026 (armada, sin publicar) · La Calculadora por rubros (opción A)
**Pedido (Ángel, 19/11):** «VAMOS CON LA A» — la Calculadora (plaza y barrio) con subíndices por rubro, como la maqueta A.

**Qué cambia (módulo `calc185` + `calc185Css`, bandera `__v185No`; no se toca nada del cálculo):**
- **Pestañas por rubro** arriba de la Calculadora: plaza **Obra · Columnas · Luminarias · Eléctrico · Civil · PAT · Resultado**; barrio **Obra · Luminarias y postes · Red aérea · Alimentación y tablero · PAT de red · Resultado**. Cada una con su **puntito**: verde = completo, naranja = falta algo (obra sin nombre, columnas en 0, vínculos en 0, cableado sin circuitos, civil sin bases ni zanja, barrio sin luminarias) o el último cálculo dejó un aviso de ese rubro; sin puntito = todas sus «Incluir esta tarea» apagadas. En el celu la fila de pestañas se desliza adentro suyo (sin scroll de costado), 64 px de alto; en la compu, las 7 en una fila.
- **Los campos de siempre**: las tarjetas no se rearman, se marcan con su rubro y se muestran las de la pestaña (mismos id, mismo `calcular()`, `restaurarFormulario`, `__calcEditar`, «Editar» del historial, el asistente `proponer_calculo`, las potencias de la v183, las validaciones y el acordeón del celu: al entrar a una pestaña sus tarjetas se abren). Obra = Datos de la obra + «¿Quién pone el material?»; Columnas = nuevas + existentes + retiros; Luminarias = vínculos y luminarias (con las potencias); Eléctrico = cableado + tablero y acometida + elementos del tablero + empalmes; Civil = obra civil + cruce; **PAT = tarjeta nueva con el esquema de conexión a tierra movido ahí** (el mismo campo) y qué sale solo. Plaza / Barrio (el mismo selector de siempre) va arriba de las pestañas; Historial y Material por obra siguen como subíndices arriba. «‹ Columnas · Eléctrico ›» al pie de cada pestaña.
- **Barra de abajo** (la `#calcFlotante` de siempre, ahora también en la compu): materiales · ≈ módulos K (el itemizado que da el cómputo, como «📥 Del cálculo de la obra»; barrio: «sin itemizado de barrio todavía») · avisos · «Cambió algo desde el último cálculo» · **⚡ Cálculos rápidos** · **Calcular** (el mismo; después va al Resultado).
- **Compu: «Lo que sale de este rubro»** al lado de cada pestaña (del último cálculo; en el celu, abajo en corto «y N más ›»), con sus avisos y las notas del cómputo plegadas.
- **Resultado:** materiales, módulos K y avisos; «Por rubro» (una tarjeta por rubro con su tabla y «✎ Cambiar» que lleva a la pestaña) · «Hoja completa · itemizado · pañol» (el resultado de siempre, con imprimir, registrar y el pañol) · «Avisos (N)». «Ver» del historial y todo lo que lleva al resultado abren la hoja completa; lo que lleva a un campo (foco, «ir a la sección», «Editar») abre su pestaña.

**A confirmar:** qué cuenta como «falta algo» en cada puntito; que los avisos del número sean solo los avisos del cálculo (las notas ⚠ que vienen siempre —normas, criterios— van plegadas en cada rubro); en qué pestaña va cada tarjeta (retiros en Columnas, empalmes en Eléctrico, «¿Quién pone el material?» en Obra; barrio: retiros en Obra, PAT de las unidades en PAT de red); el módulo K de la barra cuenta todo el itemizado previsto (también provisiones).

**Cómo se arma:** `herramientas/v185/patch_v185.py` sobre {BASE} (solo el módulo antes de `revisarAppDiag` y el sello: anda igual sobre la 181, 182 y 184). Sin reglas nuevas.

**Pruebas:** {PRU}

**Sello:** `{SELLO}` · ORIGINAL `{SHA_O}` · index `{SHA_I}`.

'''
    t = ins_antes(t, '\n## v', '\n' + txt.rstrip('\n') + '\n').replace('\n\n\n## v185', '\n\n## v185')
else:
    if '`calc185`' in t: print('ya'); sys.exit(0)
    a = '> Estado al **19/11/2026**: '
    assert a in t
    t = t.replace(a, a + f'**v185 armada, sin publicar** (**la Calculadora por rubros, opción A** —«VAMOS CON LA A»—: pestañas Obra · Columnas · Luminarias · Eléctrico · Civil · PAT · Resultado (barrio: Obra · Luminarias y postes · Red aérea · Alimentación y tablero · PAT de red · Resultado) con puntito verde / naranja; las tarjetas de siempre marcadas por rubro (mismos id y la misma cuenta; el esquema de tierra se mueve a PAT); barra de abajo con materiales, módulos K, avisos, «Calcular» y ⚡ Cálculos rápidos; en la compu «Lo que sale de este rubro» y el Resultado por rubro con «✎ Cambiar»; módulo `calc185`, bandera `__v185No`, `herramientas/v185/patch_v185.py`, sello `{SELLO}`. Sin reglas nuevas) · ', 1)
    a = '«Cálculos rápidos» (hormigón, zanja, cables, consumo, abrazaderas, caída de tensión). |'
    assert t.count(a) == 1
    t = t.replace(a, a[:-2] + ' **v185:** pestañas por rubro `#r185Tabs` (plaza `obra·col·lum·ele·civ·pat·res`, barrio `bobra·blum·bred·btab·bpat·res`; `data-r185` en cada tarjeta, `.r185-ve` la de la pestaña), `#r185Top` con Plaza / Barrio, `#r185Pat` (esquema de tierra), `#r185Nav`, `#r185Prev` «Lo que sale de este rubro», `#r185Res` (Resultado por rubro; `#resultCard` en «Hoja completa»), barra = `#calcFlotante` + `#r185Bar` + `#r185Rap`; `#subtabsCalc` escondido (vuelve con ⚡). |')
    fila = '| `calc185` + `calc185Css` | 185 | **La Calculadora por rubros, opción A** (Ángel 19/11: «VAMOS CON LA A»). Solo marca y muestra: `CARDS` {rubro: ids} (`@datos` = la tarjeta de `#obraNombre`, `@aviso` = `.cb-aviso` del barrio; `calcLimpiarBtn` en Obra; los «Calcular materiales» viejos con `data-r185="-"`); CSS esconde `[data-r185]:not(.r185-ve)` de la primera columna de `.grid`. `armarPat()` crea `#r185Pat` y MUEVE ahí `label[for=esquemaTierra]`, `#esquemaTierra`, `#esquemaHint` (fuera del `section-off` de Columnas). La `.cb-modo` de calcBarrio se mueve a `#r185Top`. `aplicar()`: clases `r185-res` / `r185-hoja` en `#viewCalculadora`, abre una vez las tarjetas acordeón de la pestaña (`st.ab`), pinta pestañas (`estado(k)`: `TOG` por pestaña + faltas + avisos del cálculo por `rubroAviso`), `#r185Nav`, `#r185Prev`, `#r185Res`, `#r185Bar`. `nuevoResultado()` (MutationObserver de `#resultCard`): `ultimoResultado` nuevo o `__computoParaAlta` («Ver»); `rubroDe(titulo, barrio)` agrupa las secciones; `modulosK(R)` = Σ cantidad × `epecItemK` de `epecPreviaDe` con una entrada temporal en el historial (como `previaCon` del asistente). «Calcular» de la barra: captura el clic de `.cf-calc`, llama `window.calcular()` (plaza o barrio) y si salió va a Resultado. Envuelve `Element.prototype.scrollIntoView` y `HTMLElement.prototype.focus` (dentro de la Calculadora: abre la pestaña del elemento; `#resultCard` → Resultado › Hoja completa), `__abrirSeccionCalculo`, `calcModoPoner`. `sessionStorage ema.calc.rubro`. Tic 1,5 s. Apagado con `__v185No`. `__calc185` {ir, tab, estado, rubroDe, porRubro, cuentas, modulosK, aplicar, tabDe, estadoInterno} |\n'
    t = ins_antes(t, '| `revisarAppDiag` | — |', fila)
    t = ins_antes(t, '- **v183:** `__v183No`', f'- **v185:** `__v185No` (la Calculadora de antes: todas las tarjetas una debajo de la otra, el acordeón del celu, la barra flotante y `#subtabsCalc`) salvo `v185:true`. `t_v185` (grupos `SOLO=0..5`, `baseDatos()` + Worker simulado): 0 = las 7 pestañas y los campos de cada una (mismos id), el esquema en PAT, puntitos de Obra y Civil, ‹ ›, celu sin scroll de costado y 44 px, barrio con sus 6 pestañas, ⚡ y Historial; 1 = «Calcular» igual que con `__v185No` (renglones e itemizado) en plaza PRFV con 75 W + 180 W, metálica de 10 m y barrio; 2 = «Editar» vuelve a cargar todo en sus pestañas, «Ver» del historial → Resultado › Hoja completa, el foco abre la pestaña; 3 = `proponer_calculo` con «Sí»; 4 = Resultado por rubro, «✎ Cambiar», «Lo que sale de este rubro» (compu) / en corto (celu), «Cambió algo…»; 5 = `__v185No`. Capturas con `CAP=carpeta`. {PRU}\n')
    t = ins_antes(t, '| 183 | ', '| 185 | La Calculadora por rubros (opción A): pestañas Obra · Columnas · Luminarias · Eléctrico · Civil · PAT · Resultado con puntito verde / naranja, los mismos campos en su pestaña, barra de abajo con materiales, módulos K, avisos, «Calcular» y ⚡, «Lo que sale de este rubro» y el Resultado por rubro con «✎ Cambiar» (`calc185`) |\n')
    t = ins_antes(t, '- **v183, a confirmar:**', '- **v185, a confirmar:** qué cuenta como «falta algo» en cada puntito (y que las notas ⚠ fijas del cómputo no pongan naranja ni sumen al número de avisos); en qué pestaña va cada tarjeta (retiros en Columnas, empalmes en Eléctrico, «¿Quién pone el material?» en Obra; barrio: retiros en Obra); los módulos K de la barra cuentan todo el itemizado previsto (con provisiones); el esquema de tierra ya no se apaga con «Incluir» de Columnas (está en PAT). Para después: los selectores propios de la maqueta (potencia / cantidad / «va en») no se hicieron: van los campos de siempre.\n')
open(sal, 'w', encoding='utf-8').write(t); print('ok', modo)
